package main

import "fmt"

type User struct {
	Name string
	Age  int
}

func main() {
	users := map[string]User{
		"张三": {Name: "张三", Age: 18},
		"李四": {Name: "李四", Age: 25},
	}
	users["王五"] = User{Name: "王五", Age: 30}
	delete(users, "李四")

	u, ok := users["张三"]
	if ok {
		u.Age = 19
		users["张三"] = u
	}

	fmt.Println("人数：", len(users))
	for name, user := range users {
		fmt.Println(name, user.Age)
	}
}
